import numpy as np
def cosine(x, y, eps=1e-12):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    nx, ny = np.linalg.norm(x), np.linalg.norm(y)
    if nx < eps or ny < eps:
        raise ValueError('zero vector has no direction')
    return float(np.dot(x, y)/(nx*ny))
